def build(out):
    P = 'dlc16'
    out.pack(P, 'Полночь в Загрузе', 'Midnight in the Boot')
    e = find(P, 'Полночь в Загрузе')
    for name, slots, cost, text, page in DECKS:
        out.add(P, 'deck', name, cost=cost, Slots=slots, Info=text + DECK_NOTE, Lib=e['id'], Page=page, Group='Кибердеки')
    for name, slots, text, page in NETWARE:
        out.add(P, 'netware', name, cost=500, Slots=slots, Info='Оборудование кибердеки; занимает ' + str(slots) + ' сл. ' + text, Lib=e['id'], Page=page, Group='Оборудование кибердеки')
